import {
	cloneVNode,
	computed,
	defineComponent,
	h,
	inject,
	nextTick,
	onBeforeUnmount,
	provide,
	ref,
	useId,
	watch,
	Teleport,
	type ComputedRef,
	type InjectionKey,
	type PropType,
} from 'vue';
import { drawerStyleKeys, getDrawerState, getDrawerTranslateStyle } from '../lib/core';
import type { DrawerDirection } from '../lib/core';
import { usePortalContainer, type PortalContainer } from '../portal';
import styles from './drawer.module.scss';

interface DrawerContextValue {
	open: boolean;
	setOpen: (open: boolean) => void;
	close: () => void;
	direction: DrawerDirection;
	modal: boolean;
	titleId: string;
	descriptionId: string;
}

type DrawerContext = ComputedRef<DrawerContextValue>;

const DrawerContextKey: InjectionKey<DrawerContext> = Symbol('tile-drawer');

function composeEventHandlers(...handlers: Array<unknown>): (event: Event) => void {
	return (event: Event) => {
		for (const handler of handlers) {
			if (!handler) {
				continue;
			}

			const list = Array.isArray(handler) ? handler : [handler];

			for (const item of list) {
				if (typeof item === 'function') {
					item(event);
				}
			}
		}
	};
}

export const Drawer = defineComponent({
	name: 'Drawer',
	props: {
		direction: { type: String as PropType<DrawerDirection>, default: 'right' },
		modal: { type: Boolean, default: true },
		open: { type: Boolean, default: undefined },
		defaultOpen: { type: Boolean, default: false },
	},
	emits: ['update:open'],
	setup(props, { emit, slots }) {
		const internalOpen = ref(props.defaultOpen);
		const isOpen = computed(() => (props.open !== undefined ? props.open : internalOpen.value));
		const baseId = useId();
		const titleId = `${baseId}-title`;
		const descriptionId = `${baseId}-description`;

		function setOpen(next: boolean) {
			if (props.open === undefined) {
				internalOpen.value = next;
			}

			emit('update:open', next);
		}

		function close() {
			setOpen(false);
		}

		const context = computed<DrawerContextValue>(() => ({
			open: isOpen.value,
			setOpen,
			close,
			direction: props.direction,
			modal: props.modal,
			titleId,
			descriptionId,
		}));

		provide(DrawerContextKey, context);

		return () => slots.default?.();
	},
});

export const DrawerTrigger = defineComponent({
	name: 'DrawerTrigger',
	props: {
		asChild: { type: Boolean, default: false },
	},
	setup(props, { slots, attrs }) {
		const contextValue = inject(DrawerContextKey);
		if (!contextValue) {
			throw new Error('DrawerTrigger must be used within <Drawer>.');
		}
		const context: DrawerContext = contextValue;

		function handleOpen() {
			context.value.setOpen(true);
		}

		return () => {
			const children = slots.default?.();
			const attrOnClick = (attrs as Record<string, unknown>).onClick;

			if (props.asChild) {
				const firstChild = Array.isArray(children) ? children[0] : children;

				if (firstChild) {
					const childProps = (firstChild.props ?? {}) as Record<string, unknown>;
					return cloneVNode(firstChild, {
						...attrs,
						onClick: composeEventHandlers(attrOnClick, childProps.onClick, handleOpen),
					});
				}
			}

			return h('button', { type: 'button', ...attrs, onClick: composeEventHandlers(attrOnClick, handleOpen) }, children);
		};
	},
});

export const DrawerClose = defineComponent({
	name: 'DrawerClose',
	props: {
		asChild: { type: Boolean, default: false },
	},
	setup(props, { slots, attrs }) {
		const contextValue = inject(DrawerContextKey);
		if (!contextValue) {
			throw new Error('DrawerClose must be used within <Drawer>.');
		}
		const context: DrawerContext = contextValue;

		function handleClose() {
			context.value.close();
		}

		return () => {
			const children = slots.default?.();
			const attrOnClick = (attrs as Record<string, unknown>).onClick;

			if (props.asChild) {
				const firstChild = Array.isArray(children) ? children[0] : children;

				if (firstChild) {
					const childProps = (firstChild.props ?? {}) as Record<string, unknown>;
					return cloneVNode(firstChild, {
						...attrs,
						onClick: composeEventHandlers(attrOnClick, childProps.onClick, handleClose),
					});
				}
			}

			return h('button', { type: 'button', ...attrs, onClick: composeEventHandlers(attrOnClick, handleClose) }, children);
		};
	},
});

export const DrawerOverlay = defineComponent({
	name: 'DrawerOverlay',
	setup(_props, { slots, attrs }) {
		const contextValue = inject(DrawerContextKey);
		if (!contextValue) {
			throw new Error('DrawerOverlay must be used within <Drawer>.');
		}
		const context: DrawerContext = contextValue;

		return () => {
			if (!context.value.open || !context.value.modal) {
				return null;
			}

			return h(
				'div',
				{
					...attrs,
					'data-state': getDrawerState(context.value.open),
					class: [styles[drawerStyleKeys.overlay], attrs.class],
					onClick: composeEventHandlers((attrs as Record<string, unknown>).onClick, () => context.value.close()),
				},
				slots.default?.(),
			);
		};
	},
});

export const DrawerContent = defineComponent({
	name: 'DrawerContent',
	props: {
		showCloseButton: { type: Boolean, default: true },
		container: { type: Object as PropType<PortalContainer>, default: null },
	},
	setup(props, { slots, attrs }) {
		const portalContainer = usePortalContainer(() => props.container);
		const contextValue = inject(DrawerContextKey);
		if (!contextValue) {
			throw new Error('DrawerContent must be used within <Drawer>.');
		}
		const context: DrawerContext = contextValue;
		const contentRef = ref<HTMLElement | null>(null);
		const previousOverflow = ref('');
		const isVisible = ref(false);
		let animationFrame = 0;
		let previouslyFocused: HTMLElement | null = null;

		function handleKeyDown(event: KeyboardEvent) {
			if (event.key === 'Escape' && context.value.modal) {
				context.value.close();
				return;
			}

			if (event.key === 'Tab' && context.value.modal) {
				const container = contentRef.value;
				if (!container) {
					return;
				}
				const focusables = Array.from(
					container.querySelectorAll<HTMLElement>(
						'a[href], button:not([disabled]), input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])',
					),
				).filter((el) => el.getClientRects().length > 0);
				if (focusables.length === 0) {
					event.preventDefault();
					return;
				}
				const first = focusables[0];
				const last = focusables[focusables.length - 1];
				const active = document.activeElement;

				if (event.shiftKey) {
					if (active === first || active === container || !container.contains(active)) {
						event.preventDefault();
						last.focus();
					}
				} else if (active === last || !container.contains(active)) {
					event.preventDefault();
					first.focus();
				}
			}
		}

		watch(
			() => context.value.open,
			(open) => {
				if (typeof document === 'undefined') {
					return;
				}

				if (open) {
					isVisible.value = false;
					previouslyFocused = document.activeElement as HTMLElement | null;
					previousOverflow.value = document.body.style.overflow;
					if (context.value.modal) {
						document.body.style.overflow = 'hidden';
					}
					document.addEventListener('keydown', handleKeyDown);
					animationFrame = requestAnimationFrame(() => {
						isVisible.value = true;
					});
					nextTick(() => {
						contentRef.value?.focus();
					});
				} else {
					cancelAnimationFrame(animationFrame);
					document.removeEventListener('keydown', handleKeyDown);
					document.body.style.overflow = previousOverflow.value;
					previouslyFocused?.focus();
				}
			},
			{ immediate: true },
		);

		onBeforeUnmount(() => {
			cancelAnimationFrame(animationFrame);
			document.removeEventListener('keydown', handleKeyDown);
			document.body.style.overflow = previousOverflow.value;
			previouslyFocused?.focus();
		});

		return () => {
			if (!context.value.open) {
				return null;
			}

			const contentChildren: any[] = [h('div', { class: styles[drawerStyleKeys.handle] })];
			const slotChildren = slots.default?.() ?? [];
			for (const child of slotChildren) {
				contentChildren.push(child);
			}

			if (props.showCloseButton) {
				contentChildren.push(
					h(
						'button',
						{
							type: 'button',
							'aria-label': '关闭',
							class: styles[drawerStyleKeys.close],
							onClick: () => context.value.close(),
						},
						[
							h(
								'svg',
								{
									class: styles[drawerStyleKeys.xIcon],
									xmlns: 'http://www.w3.org/2000/svg',
									width: '16',
									height: '16',
									viewBox: '0 0 24 24',
									fill: 'none',
									stroke: 'currentColor',
									'stroke-width': '2',
									'stroke-linecap': 'round',
									'stroke-linejoin': 'round',
									'aria-hidden': 'true',
								},
								[h('path', { d: 'M18 6 6 18' }), h('path', { d: 'm6 6 12 12' })],
							),
						],
					),
				);
			}

			const userClass = attrs.class;
			const contentAttrs = { ...attrs };
			delete contentAttrs.class;

			return h(Teleport, { to: portalContainer.value }, [
				context.value.modal
					? h('div', {
							'data-state': getDrawerState(context.value.open),
							class: styles[drawerStyleKeys.overlay],
							onClick: () => context.value.close(),
						})
					: null,
				h(
					'div',
					{
						...contentAttrs,
						ref: contentRef,
						role: 'dialog',
						'aria-modal': context.value.modal ? 'true' : 'false',
						'aria-labelledby': context.value.titleId,
						'aria-describedby': context.value.descriptionId,
						tabindex: -1,
						'data-state': getDrawerState(context.value.open),
						'data-direction': context.value.direction,
						style: {
							transform: isVisible.value ? undefined : getDrawerTranslateStyle(context.value.direction),
							opacity: isVisible.value ? undefined : 0,
						},
						class: [styles[drawerStyleKeys.content], userClass],
					},
					contentChildren,
				),
			]);
		};
	},
});

export const DrawerHeader = defineComponent({
	name: 'DrawerHeader',
	setup(_props, { slots, attrs }) {
		return () => h('div', { ...attrs, class: [styles[drawerStyleKeys.header], attrs.class] }, slots.default?.());
	},
});

export const DrawerFooter = defineComponent({
	name: 'DrawerFooter',
	setup(_props, { slots, attrs }) {
		return () => h('div', { ...attrs, class: [styles[drawerStyleKeys.footer], attrs.class] }, slots.default?.());
	},
});

export const DrawerTitle = defineComponent({
	name: 'DrawerTitle',
	setup(_props, { slots, attrs }) {
		const contextValue = inject(DrawerContextKey);
		if (!contextValue) {
			throw new Error('DrawerTitle must be used within <Drawer>.');
		}
		const context: DrawerContext = contextValue;

		return () => h('h2', { ...attrs, id: context.value.titleId, class: [styles[drawerStyleKeys.title], attrs.class] }, slots.default?.());
	},
});

export const DrawerDescription = defineComponent({
	name: 'DrawerDescription',
	setup(_props, { slots, attrs }) {
		const contextValue = inject(DrawerContextKey);
		if (!contextValue) {
			throw new Error('DrawerDescription must be used within <Drawer>.');
		}
		const context: DrawerContext = contextValue;

		return () => h('p', { ...attrs, id: context.value.descriptionId, class: [styles[drawerStyleKeys.description], attrs.class] }, slots.default?.());
	},
});

export default Drawer;

@use '../../../styles/variables/colors' as *;

// 半透明遮罩
.overlay {
	position: fixed;
	inset: 0;
	z-index: $z-modal;
	background-color: var(--tile-drawer-overlay, $overlay);

	&[data-state='open'] {
		animation: drawer-overlay-in $transition-normal;
	}

	&[data-state='closed'] {
		opacity: 0;
	}
}

@keyframes drawer-overlay-in {
	from {
		opacity: 0;
	}

	to {
		opacity: 1;
	}
}

// 抽屉内容面板
.content {
	position: fixed;
	z-index: $z-modal;
	display: flex;
	flex-direction: column;
	background-color: var(--tile-drawer-background, $card);
	color: $card-foreground;
	box-shadow: var(--tile-drawer-shadow, $shadow-lg);
	outline: none;
	transition:
		transform $transition-slow,
		opacity $transition-fast;

	&[data-direction='right'] {
		inset: 0 0 0 auto;
		width: 75%;
		height: 100%;
		max-width: 24rem;
		border-left: 1px solid var(--tile-drawer-border, $border);
	}

	&[data-direction='left'] {
		inset: 0 auto 0 0;
		width: 75%;
		height: 100%;
		max-width: 24rem;
		border-right: 1px solid var(--tile-drawer-border, $border);
	}

	&[data-direction='top'] {
		inset: 0 0 auto 0;
		width: 100%;
		max-height: 80vh;
		border-bottom: 1px solid var(--tile-drawer-border, $border);
	}

	&[data-direction='bottom'] {
		inset: auto 0 0 0;
		width: 100%;
		max-height: 80vh;
		border-top: 1px solid var(--tile-drawer-border, $border);
	}
}

// 顶部 / 底部方向的手柄
.handle {
	margin: $spacing-4 auto 0;
	display: none;
	height: 0.5rem;
	width: 100px;
	flex-shrink: 0;
	border-radius: $radius-full;
	background-color: var(--tile-drawer-handle-background, $muted);
}

.content[data-direction='top'] .handle,
.content[data-direction='bottom'] .handle {
	display: block;
}

// 右上角关闭按钮
.close {
	position: absolute;
	top: $spacing-4;
	right: $spacing-4;
	display: inline-flex;
	align-items: center;
	justify-content: center;
	padding: $spacing-1;
	border: none;
	border-radius: $radius;
	background-color: transparent;
	color: $muted-foreground;
	opacity: 0.7;
	cursor: pointer;
	transition: opacity $transition-fast;
	outline: none;

	&:hover {
		opacity: 1;
	}

	&:focus-visible {
		box-shadow: var(--tile-drawer-close-focus-shadow, 0 0 0 2px $background, 0 0 0 4px $ring);
	}

	.xIcon {
		width: 1rem;
		height: 1rem;
		pointer-events: none;
	}
}

.header {
	display: flex;
	flex-direction: column;
	gap: $spacing-1_5;
	padding: var(--tile-drawer-header-padding, $spacing-4);
}

.footer {
	margin-top: auto;
	display: flex;
	flex-direction: column;
	gap: $spacing-2;
	padding: var(--tile-drawer-footer-padding, $spacing-4);
}

.title {
	margin: 0;
	font-size: var(--tile-drawer-title-size, $text-base);
	font-weight: $font-semibold;
	line-height: var(--tile-drawer-title-leading, $leading-none);
	color: $foreground;
}

.description {
	margin: 0;
	font-size: $text-sm;
	line-height: $leading-normal;
	color: var(--tile-drawer-description-color, $muted-foreground);
}
